# ── 本向导自有 helpers（不属于 wizard library） ────────────────────────────
# confirm_strict "question"：显式 y/n 门，空回车不算答复而是重新提问。
# wizard library 的 confirm 是 [y/N]（空回车 = 取消），本向导每个阶段都用这个，
# 因为“没表态”在安装/启动这种不可轻易回退的步骤上不该被当成任何一种答复。
# 只接受 y/yes / n/no；EOF（Ctrl-D 或 stdin 断开）视为取消，绝不自动继续。
confirm_strict() {
    local reply=""
    while :; do
        printf '  %s? %s [y/n] ' "$YELLOW" "$1"
        read -r reply || { printf '\n'; return 1; }
        case "$reply" in
            [Yy] | [Yy][Ee][Ss]) return 0 ;;
            [Nn] | [Nn][Oo]) return 1 ;;
            *) printf '  %s请明确输入 y 或 n（空回车不算答复）%s\n' "$DIM" "$RESET" ;;
        esac
    done
}

die() { printf '\n  %s✖ %s%s\n\n' "$YELLOW" "$1" "$RESET" >&2; exit 1; }
okf() { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }
notef() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
problem() { PROBLEMS+=("$1"); printf '  %s✖%s %s\n' "$YELLOW" "$RESET" "$1"; }
problem_summary() {
    ((${#PROBLEMS[@]} == 0)) && return 0
    printf '\n  %s%d 个问题需要先处理：%s\n' "$YELLOW" "${#PROBLEMS[@]}" "$RESET"
    local item
    for item in "${PROBLEMS[@]}"; do printf '    - %s\n' "$item"; done
    printf '\n'
}

usage() {
    cat <<'USAGE'
scripts/setup-local-deployment.sh —— 本机「与云端同形式」部署交互向导

用法：
  scripts/setup-local-deployment.sh
  scripts/setup-local-deployment.sh --check
