  scripts/setup-local-deployment.sh --help

期望版本（锚点）来源（绝不从安装包内 VERSION/MANIFEST 反推）：
  * 默认：正在运行的受信脚本所在开发仓库的已提交 HEAD（且必须等于 main，脚本自身须与 HEAD 一致）；
  * --commit：操作者显式给出完整 40 位 SHA（只用于回归旧包，例如 --commit e582… 配旧包）。

参数：
  --package DIR   指向 scripts/prepare-local-deployment-package.sh 产出的目录
                  （默认 $BILI_DEPLOY_PACKAGE，否则 /var/tmp/bili-local-deployment/<锚点短SHA>）
  --commit SHA    显式锚点（40 位十六进制完整提交 SHA）
  --check         只读预检：校验 MANIFEST/bundle/路径/端口/账号，打印安装计划；
                  不写任何文件、不调用 sudo。可安全重复执行。
  --help          显示本帮助

说明：
  * 以普通用户运行；需要 root 的步骤由脚本按需调用 sudo，密码只在你的 TTY 输入。
  * 阶段顺序：预检 → 依赖→账号与目录 → 代码与依赖 → 系统配置 → 前端发布 → 校验与启动。
  * 唯一配置差异：网页 listen 127.0.0.1:4273（云端 4173）；API 与 proxy_pass 仍是 8000。
  * 本机不启用 OSS/Cookie/飞书通知（变量保持不设置），只托管 API＋collector 两进程。
USAGE
}

sha_of() { sha256sum -- "$1" 2>/dev/null | cut -d' ' -f1; }
pkg_file() { printf '%s/%s' "$PACKAGE_DIR" "$1"; }

state_load() {
    STATE=()
    [[ -r "$STATE_FILE" ]] || return 0
    local key value
    while IFS=$'\t' read -r key value; do
        [[ -z "$key" || "$key" == \#* ]] && continue
        STATE["$key"]="${value:-}"
    done <"$STATE_FILE"
}
state_get() { printf '%s' "${STATE[$1]:-}"; }
state_set() { STATE["$1"]="${2:-}"; }
state_save() {
    local tmp key
    tmp="$(mktemp /var/tmp/bili-local-state.XXXXXX)"
    {
        printf '# bili-local-deployment state v1（root 拥有；本脚本唯一可信的“自己创建的对象”记录）\n'
        for key in "${!STATE[@]}"; do printf '%s\t%s\n' "$key" "${STATE[$key]}"; done |
            LC_ALL=C sort
    } >"$tmp"
    sudo install -D -m 0644 -o root -g root "$tmp" "$STATE_FILE"
    rm -f "$tmp"
}

# path_owner 打印 absent|ours|modified|unknown；只认本脚本 state 记录，绝不猜测。
path_owner() {
    local path="$1"
    if [[ ! -e "$path" && ! -L "$path" ]]; then
        printf 'absent'
        return 0
    fi
    # 首启迁移创建的库由 db: 记录（库内容永远不安装、不覆盖、不删除）
    if [[ -n "${STATE[db:$path]:-}" && -f "$path" ]]; then
        printf 'db'
        return 0
    fi
    if [[ -n "${STATE[file:$path]:-}" ]]; then
        if [[ -f "$path" ]]; then
            local recorded actual
            recorded="${STATE[file:$path]}"
            actual="$(sha_of "$path")"
            if [[ -z "$actual" ]]; then
                # root 私有文件（例如 env 0600）普通用户读不了内容：先按记录放行，
                # 安装阶段会用 sudo 复核真实 SHA256，不一致就拒绝覆盖。
                printf 'ours'
            elif [[ "$actual" == "$recorded" ]]; then
                printf 'ours'
            else
                printf 'modified'
            fi
        else
            printf 'modified'
        fi
        return 0
    fi
    if [[ -n "${STATE[dir:$path]:-}" || -n "${STATE[symlink:$path]:-}" ]]; then
        printf 'ours'
        return 0
    fi
    printf 'unknown'
}

require_managed() {
    local path="$1" label="$2" owner
    owner="$(path_owner "$path")"
    case "$owner" in
        absent | ours) return 0 ;;
        db) die "$label 是本机数据库文件，本向导不安装、不覆盖、不删除：$path（请人工确认后处理）" ;;
        modified) die "$label 已被修改：$path（SHA256 与上次安装记录不一致）；本向导拒绝覆盖。请保留现文件、备份与状态，不删除、不移动真实配置、不手改 state，并按 docs/deployment/README.md 人工核查来源后处理" ;;
        *) die "$label 是未识别的已存在对象：$path；默认拒绝覆盖。请人工确认来源后移走/改名（**不要直接删除数据库或真实配置**），再重跑" ;;
    esac
}

need_tty() { [[ -t 0 && -t 1 ]] || die "需要在你的终端交互运行（sudo 密码不会被脚本捕获或保存）"; }

sudo_auth() {
    need_tty
    notef "sudo 只会在你的终端提示密码；脚本不读取、不保存、不打印密码，也不修改 sudoers。"
    sudo -v || die "sudo 授权失败；未做进一步改动"
}

run_as_bili() {
    sudo -u "$RUN_USER" env -i \
        "HOME=/home/$RUN_USER" "USER=$RUN_USER" "LOGNAME=$RUN_USER" \
        PATH=/usr/local/bin:/usr/bin:/bin "LANG=C.UTF-8" "TMPDIR=/var/tmp" \
        "$@"
}

port_busy() { ss -H -ltn "sport = :$1" 2>/dev/null | grep -q .; }
# 可替换 seam：测试需模拟“宿主未安装 nginx”，不能依赖 command -v 的真实结果。
nginx_available() { command -v nginx >/dev/null 2>&1; }
listen_addrs() { ss -H -ltn "sport = :$1" 2>/dev/null | awk '{print $4}' | paste -sd, -; }
http_code() { curl -sS -o /dev/null -m 5 -w '%{http_code}' "$1" 2>/dev/null || true; }

# assert_trusted_package 建立“root 会安装这些字节”的信任锚：
#   * 包目录与每一级祖先：属主只能是当前操作员或 root；
#   * 祖先 group/other 可写只允许 root 拥有且带 sticky（/var/tmp 1777 的合法特例）；
#   * 包内不得有符号链接、设备/fifo/socket，不得有 group/other 可写条目。
assert_trusted_package() {
    local path="$1" dir owner mode gow sticky first
    dir="$(readlink -f "$path" 2>/dev/null || true)"
    [[ -n "$dir" && -d "$dir" ]] || die "无法解析安装包真实路径：$path"
    while :; do
        owner="$(stat -c %u "$dir")"
        mode="$(stat -c %a "$dir")"
        gow=$((8#$mode & 8#022))
        sticky=$((8#$mode & 8#1000))
        if [[ "$owner" != "$EUID" && "$owner" != "0" ]]; then
            die "安装包路径含非本人/非 root 拥有的目录：$dir（owner=$owner）；拒绝以 root 安装他人可控内容"
        fi
        if ((gow != 0)) && ! { [[ "$owner" == "0" ]] && ((sticky != 0)); }; then
            die "安装包路径含 group/other 可写且非 root+sticky 的目录：$dir（mode=$mode owner=$owner）；拒绝使用"
        fi
        [[ "$dir" == "/" ]] && break
        dir="$(dirname "$dir")"
    done
    first="$(find "$path" -type l -print -quit)"
    [[ -z "$first" ]] || die "安装包内含符号链接（root 安装不得跟随链接）：$first"
    first="$(find "$path" ! -type f ! -type d -print -quit)"
    [[ -z "$first" ]] || die "安装包内含非普通文件（设备/fifo/socket）：$first"
    first="$(find "$path" -perm /022 -print -quit)"
    [[ -z "$first" ]] || die "安装包目录内有 group/other 可写的条目：$first"
}

verify_package() {
    local path="$1" want_uv got_uv
    [[ -d "$path" ]] || die "安装包目录不存在：$path（先运行 scripts/prepare-local-deployment-package.sh）"
    [[ -f "$path/MANIFEST.sha256" ]] || die "安装包缺少 MANIFEST.sha256：$path"
    [[ -r "$path/VERSION" ]] || die "安装包缺少 VERSION：$path"
    assert_trusted_package "$path"
    ( cd "$path" && sha256sum --check --strict --quiet MANIFEST.sha256 ) ||
        die "安装包 MANIFEST 校验失败（内容被改动或不完整）；拒绝继续：$path"
    [[ -x "$path/uv/uv" ]] || die "安装包缺少可执行 uv/uv：$path"
    want_uv="$(sed -n 's/^uv=//p' "$path/VERSION" | head -n1)"
    got_uv="$("$path/uv/uv" --version 2>/dev/null || true)"
    [[ "$want_uv" == "$got_uv" ]] || die "包内 uv 与 VERSION 记录不一致（记录 '$want_uv'，实跑 '$got_uv'）；拒绝使用：$path"
}

# resolve_anchor 取得“进入向导时固定的外部锚点”。期望版本只来自受信脚本仓库或操作者显式指定，
# 绝不从包内 VERSION/MANIFEST 反推（否则被替换的包可以自证版本）。
resolve_anchor() {
    if [[ -n "$CLI_COMMIT" ]]; then
        [[ "$CLI_COMMIT" =~ ^[0-9a-f]{40}$ ]] ||
            die "--commit 需要完整 40 位十六进制 SHA（收到：$CLI_COMMIT）"
        ANCHOR_COMMIT="$CLI_COMMIT"
        ANCHOR_SOURCE="operator(--commit)"
        return 0
    fi
    DEV_REPO="$(git -C "$SCRIPT_DIR" rev-parse --show-toplevel 2>/dev/null || true)"
    [[ -n "$DEV_REPO" ]] ||
        die "无法从脚本位置（$SCRIPT_DIR）定位受信开发仓库；请从已提交的仓库运行，或用 --commit <40位SHA> 显式指定锚点"
    ANCHOR_COMMIT="$(git -C "$DEV_REPO" rev-parse --verify 'HEAD^{commit}' 2>/dev/null || true)"
    [[ "$ANCHOR_COMMIT" =~ ^[0-9a-f]{40}$ ]] ||
        die "无法从受信仓库 HEAD 取得提交锚点：$DEV_REPO"
    local main_commit blob want got dirty
    main_commit="$(git -C "$DEV_REPO" rev-parse --verify 'refs/heads/main^{commit}' 2>/dev/null || true)"
    [[ "$main_commit" == "$ANCHOR_COMMIT" ]] ||
        die "受信仓库 HEAD（$ANCHOR_COMMIT）不等于 main（${main_commit:-无}）：安装包必须从已合入 main 的提交安装"
    blob="$(git -C "$DEV_REPO" rev-parse --verify 'HEAD:scripts/setup-local-deployment.sh' 2>/dev/null || true)"
    [[ -n "$blob" ]] ||
        die "受信 HEAD 中没有 scripts/setup-local-deployment.sh：请先从已提交版本运行（或用 --commit 做旧包回归）"
    want="$(git -C "$DEV_REPO" cat-file blob "$blob" | sha256sum | cut -d' ' -f1)"
    got="$(sha256sum -- "$SCRIPT_PATH" | cut -d' ' -f1)"
    [[ "$want" == "$got" ]] ||
        die "正在运行的脚本与受信 HEAD 中的版本不一致（脚本未提交或被改动）：请从已提交的 main 运行，或用 --commit 显式锚点"
    dirty="$(git -C "$DEV_REPO" status --porcelain=v1 -- scripts/setup-local-deployment.sh scripts/prepare-local-deployment-package.sh 2>/dev/null || true)"
    [[ -z "$dirty" ]] || die "运维脚本在受信仓库里有未提交改动：$dirty（提交后再正式安装；旧包回归请用 --commit）"
    ANCHOR_SOURCE="repo-head($DEV_REPO)"
}

anchor_short() { printf '%s' "${ANCHOR_COMMIT:0:7}"; }
default_package_dir() { printf '/var/tmp/bili-local-deployment/%s' "$(anchor_short)"; }
anchor_label() { printf '%s（%s）' "$(anchor_short)" "$ANCHOR_SOURCE"; }

# assert_anchor_stable 在每次 root 写入前调用：锚点与包提交都必须仍等于进入向导时的值；
# 受信仓库 HEAD 中途变动一律拒绝（显式 --commit 模式不依赖 HEAD，故只校验包提交）。
assert_anchor_stable() {
    local now
    case "$ANCHOR_SOURCE" in
        repo-head*)
            now="$(git -C "$DEV_REPO" rev-parse --verify 'HEAD^{commit}' 2>/dev/null || true)"
            [[ "$now" == "$ANCHOR_COMMIT" ]] ||
                die "受信仓库 HEAD 在向导运行期间变了（$ANCHOR_COMMIT → ${now:-未知}）；拒绝在变动中的源码上继续 root 写入"
            ;;
    esac
    [[ "$COMMIT" == "$ANCHOR_COMMIT" ]] ||
        die "安装包提交（${COMMIT:-未知}）与进入向导时固定的锚点 $ANCHOR_COMMIT 不一致；拒绝继续"
}

resolve_package() {
    [[ -n "$PACKAGE_DIR" ]] && return 0
    if [[ -n "${BILI_DEPLOY_PACKAGE:-}" ]]; then
        PACKAGE_DIR="$BILI_DEPLOY_PACKAGE"
        return 0
    fi
    local expected root candidate
    local -a candidates=()
    expected="$(default_package_dir)"
    if [[ -d "$expected" ]]; then
        PACKAGE_DIR="$expected"
        return 0
    fi
    # 兜底：/var/tmp 下唯一且 VERSION.commit == 锚点 的子目录（版本不符不采用）
    root=/var/tmp/bili-local-deployment
    if [[ -d "$root" ]]; then
        while IFS= read -r candidate; do
            [[ "$(sed -n 's/^commit=//p' "$candidate/VERSION" 2>/dev/null | head -n1)" == "$ANCHOR_COMMIT" ]] &&
                candidates+=("$candidate")
        done < <(find "$root" -mindepth 1 -maxdepth 1 -type d -print | LC_ALL=C sort)
    fi
    ((${#candidates[@]} == 1)) && { PACKAGE_DIR="${candidates[0]}"; return 0; }
    die "未找到锚点 $(anchor_short) 对应的安装包：$expected（先运行 scripts/prepare-local-deployment-package.sh，或用 --package 指定同版本目录）"
}

install_managed() {
    local rel="$1" dst="$2" mode="$3" src new_sha recorded current_sha
    src="$PACKAGE_DIR/$rel"
    [[ -f "$src" ]] || die "安装包缺少文件：$rel"
    new_sha="$(sha_of "$src")"
    recorded="$(state_get "file:$dst")"
    if [[ -f "$dst" ]]; then
        current_sha="$(sudo sha256sum -- "$dst" 2>/dev/null | cut -d' ' -f1)"
        if [[ -n "$current_sha" && "$current_sha" == "$new_sha" ]]; then
            state_set "file:$dst" "$new_sha"
            okf "已是最新：$dst"
            return 0
        fi
        if [[ -z "$recorded" || "$current_sha" != "$recorded" ]]; then
            die "拒绝覆盖未知/已修改的 $dst（现内容与上次安装记录不一致）；请人工确认并移走/改名（不要删除数据库或真实配置）后重跑"
        fi
        okf "覆盖本向导上次安装且未被修改的：$dst"
    fi
    sudo install -D -m "$mode" -o root -g root "$src" "$dst" || die "安装失败：$dst"
    [[ "$(sudo sha256sum -- "$dst" | cut -d' ' -f1)" == "$new_sha" ]] || die "安装后校验失败：$dst"
    state_set "file:$dst" "$new_sha"
    CONFIG_CHANGED=1
    okf "已安装：$dst（$mode root:root）"
}

# ── 发行包默认 nginx.conf 的处理（B4：新装 Arch/CachyOS 自带激活的 listen 80） ──
# 原则：只对「本次由本向导新装 + 与本地缓存同版本包逐字节相同」的原始配置动手；
# 拿不到可信原始包、文件被改过、或 nginx 在本次运行前就已存在，一律 fail closed（不动任何文件）。

nginx_installed_version() { LC_ALL=C pacman -Q nginx 2>/dev/null | awk '{print $2}'; }

# find_cached_nginx_pkg echo 唯一可信的同版本缓存包路径；0=恰好一个，1=版本未知，2=没有缓存，3=多个候选
find_cached_nginx_pkg() {
    local ver pkg
    local -a hits=()
    ver="$(nginx_installed_version)"
    [[ -n "$ver" ]] || return 1
    shopt -s nullglob
    for pkg in "$PACMAN_PKG_CACHE"/nginx-"$ver"-*.pkg.tar.zst \
        "$PACMAN_PKG_CACHE"/nginx-"$ver"-*.pkg.tar.xz; do
        hits+=("$pkg")
    done
    shopt -u nullglob
    case "${#hits[@]}" in
        1) printf '%s' "${hits[0]}" ;;
        0) return 2 ;;
        *) return 3 ;;
    esac
}

# 用 bsdtar 从缓存包里只读提取包原始配置（不安装、不解包到系统）
extract_pkg_nginx_conf() { # $1 pkg $2 out
    bsdtar -xOf "$1" "$NGINX_STOCK_CONF" >"$2" 2>/dev/null && [[ -s "$2" ]]
}

# write_managed_nginx_main 输出固定的受管 main：只有 events/http 骨架 + mime.types + conf.d include，
# 不含任何 server/默认站点，因此不可能继承发行包默认的 listen 80。
write_managed_nginx_main() { # $1 out $2 modules|no-modules
    local out="$1" with_modules="$2"
    {
        printf '# 本机受管 nginx 主配置（bili_charge_dynamics 部署向导生成，不是发行版原始文件）\n'
        printf '# 发行包原始配置已备份到 /var/lib/bili-local-deployment/backups/（root 0600）。\n'
        printf '# 刻意不含任何 server 块：站点全部来自下面的 conf.d/*.conf，避免继承默认 listen 80。\n'
        printf 'worker_processes auto;\n\n'
        if [[ "$with_modules" == "modules" ]]; then
            printf 'include modules.d/*.conf;\n\n'
        fi
        printf 'events {\n    worker_connections 1024;\n}\n\n'
        printf 'http {\n'
        printf '    include %s/mime.types;\n' "$NGINX_ROOT"
        printf '    default_type application/octet-stream;\n'
        printf '    types_hash_max_size 2048;\n'
        printf '    sendfile on;\n'
        printf '    keepalive_timeout 65;\n'
        printf '    include %s/conf.d/*.conf;\n' "$NGINX_ROOT"
        printf '}\n'
    } >"$out"
}

# ensure_nginx_main：
#   A. 已登记为受管 main（上次已规范化）→ 只接受内容仍等于登记值，重跑不当作未知；
#   B. 未登记 → 只处理“本次新装 + pacman 拥有 + 与缓存包原始配置逐字节相同”的发行版默认配置：
#      备份原始文件（root 0600）→ 写入固定受管 main → nginx -t，失败按原 mode 回滚。
ensure_nginx_main() {
    [[ -f "$NGINX_MAIN" ]] || die "缺少 $NGINX_MAIN（nginx 包安装异常）"

    local recorded current
    recorded="$(state_get "file:$NGINX_MAIN")"
    if [[ -n "$recorded" ]]; then
        current="$(sudo sha256sum -- "$NGINX_MAIN" 2>/dev/null | cut -d' ' -f1)"
        [[ "$current" == "$recorded" ]] ||
            die "受管 nginx 主配置已被改动：$NGINX_MAIN（本向导拒绝覆盖；请人工确认后移走/恢复再重跑）"
        grep -qE '^[[:space:]]*include[[:space:]]+[^;]*conf\.d/\*\.conf[[:space:]]*;' "$NGINX_MAIN" ||
            die "受管 nginx 主配置缺少 conf.d include（内容与登记值一致但不完整）；请人工检查后移走再重跑"
        # 迁移闸门：旧版向导只“加 include”，会把仍带默认 server/listen 80 的文件登记成受管。
        # 这种登记值不能当安全版本续跑；一律交人工，绝不自动改写。
        if grep -qE '^[[:space:]]*(server[[:space:]]*\{|listen[[:space:]])' "$NGINX_MAIN"; then
            die "登记过的受管 nginx 主配置仍含 server/listen（可能是旧版向导留下的默认站点）；本向导不自动改写，也不建议手工改配置或 state。请保留现文件与其备份、保留 $STATE_FILE 不动（不删除、不移动真实配置、不手改 state），停止安装，并按 docs/deployment/README.md 人工核查来源后再处理。"
        fi
        okf "nginx 主配置是本向导登记过的受管版本（无默认 server、无 80 监听）"
        return 0
    fi

    local fresh ver pkg tmp_orig tmp_new backup mode current_sha pkg_sha modules
    fresh="$(state_get "pkg:nginx-fresh-install")"
    [[ -n "$fresh" ]] ||
        die "$NGINX_MAIN 未登记为受管版本，且 nginx 不是本次运行新装的。本向导不自动改写未知/既有/人工 nginx 配置（fail closed）：请保留现文件、备份与状态，不删除、不移动真实配置、不手改 state，并按 docs/deployment/README.md 人工核查来源后处理。"

    ver="$(nginx_installed_version)"
    [[ -n "$ver" && "$ver" == "$fresh" ]] ||
        die "nginx 版本与本次新装记录不一致（记录 ${fresh:-无}，当前 ${ver:-未知}）；拒绝自动改写（fail closed）"

    LC_ALL=C pacman -Qo "$NGINX_MAIN" >/dev/null 2>&1 ||
        die "$NGINX_MAIN 不属于任何已安装包（可能被替换/移动）；拒绝自动改写（fail closed）"

    pkg="$(find_cached_nginx_pkg)" || {
        case "$?" in
            1) die "取不到已安装的 nginx 包版本，无法核验原始配置（fail closed）" ;;
            2) die "本机没有 nginx $ver 的缓存包（${PACMAN_PKG_CACHE}/nginx-${ver}-*.pkg.tar.*），无法逐字节证明原始配置；拒绝自动改写（fail closed）。可先用 pacman -Sw nginx 取缓存，或人工处理默认 server。" ;;
            *) die "缓存里有多个 nginx $ver 归档，无法确定原始配置；拒绝自动改写（fail closed）" ;;
        esac
    }

    tmp_orig="$(mktemp /var/tmp/bili-nginx-orig.XXXXXX)"
    tmp_new="$(mktemp /var/tmp/bili-nginx-new.XXXXXX)"
    extract_pkg_nginx_conf "$pkg" "$tmp_orig" ||
        die "无法从缓存包提取 $NGINX_STOCK_CONF：$pkg（fail closed；未改动系统文件）"
    if grep -qE '^[[:space:]]*load_module[[:space:]]' "$tmp_orig"; then
        rm -f "$tmp_orig" "$tmp_new"
        die "包原始 nginx.conf 使用 load_module（动态模块）；本向导不自动改写（fail closed），请人工处理"
    fi
    modules="no-modules"
    grep -qE '^[[:space:]]*include[[:space:]]+modules\.d/\*\.conf[[:space:]]*;' "$tmp_orig" && modules="modules"

    current_sha="$(sudo sha256sum -- "$NGINX_MAIN" | cut -d' ' -f1)"
    pkg_sha="$(sha256sum -- "$tmp_orig" | cut -d' ' -f1)"
    if [[ "$current_sha" != "$pkg_sha" ]]; then
        # F2 中断恢复：写盘成功但没来得及登记时，现文件应等于“同一生成器”的预期受管 main。
        # 只有在本次新装来源、pacman 归属、缓存包原文都已成立的前提下才走到这里；
        # 逐字节一致才补登记（绝不重写系统文件），不一致照旧拒绝，不接管任意未知配置。
        local tmp_expected
        tmp_expected="$(mktemp /var/tmp/bili-nginx-expect.XXXXXX)"
        write_managed_nginx_main "$tmp_expected" "$modules" || {
            rm -f "$tmp_orig" "$tmp_new" "$tmp_expected"
            die "生成受管 nginx 主配置失败"
        }
        if cmp -s "$tmp_expected" "$NGINX_MAIN"; then
            state_set "file:$NGINX_MAIN" "$current_sha"
            state_save
            rm -f "$tmp_orig" "$tmp_new" "$tmp_expected"
            okf "检测到本向导已写入的受管 main 但状态未落盘（中断恢复）：只补登记 $current_sha，未重写系统文件"
            return 0
        fi
        rm -f "$tmp_orig" "$tmp_new" "$tmp_expected"
        die "$NGINX_MAIN 既不是包原始配置、也不是本向导应生成的受管 main（可能被人工修改或来源不明）；本向导 fail closed，未改动系统文件。请保留现文件与其备份、保留 $STATE_FILE 不动（不删除、不移动真实配置、不手改 state），停止安装，并按 docs/deployment/README.md 人工核查来源后再处理。"
    fi
    [[ -f "$NGINX_ROOT/mime.types" ]] || {
        rm -f "$tmp_orig" "$tmp_new"
        die "缺少 $NGINX_ROOT/mime.types（由 mailcap 提供）；拒绝改写主配置（fail closed）"
    }
    write_managed_nginx_main "$tmp_new" "$modules" || {
        rm -f "$tmp_orig" "$tmp_new"
        die "生成受管 nginx 主配置失败"
    }

    backup="$BACKUP_STATE_DIR/nginx.conf.$(date -u +%Y%m%dT%H%M%SZ).orig"
    mode="$(stat -c %a "$NGINX_MAIN")"
    sudo install -d -m 0700 -o root -g root "$BACKUP_STATE_DIR" || die "创建备份目录失败：$BACKUP_STATE_DIR"
    sudo install -D -m 0600 -o root -g root "$NGINX_MAIN" "$backup" || die "备份 nginx.conf 失败"
    sudo install -m "$mode" -o root -g root "$tmp_new" "$NGINX_MAIN" || {
        rm -f "$tmp_orig" "$tmp_new"
        die "写入受管 nginx 主配置失败；原始配置仍在 $backup"
    }
    if ! sudo nginx -t >/dev/null 2>&1; then
        sudo install -m "$mode" -o root -g root "$backup" "$NGINX_MAIN"
        rm -f "$tmp_orig" "$tmp_new"
        die "受管 nginx 主配置未通过 nginx -t，已从 $backup 按原 mode 恢复发行版原始配置"
    fi
    state_set "backup:$NGINX_MAIN" "$backup"
    state_set "file:$NGINX_MAIN" "$(sudo sha256sum -- "$NGINX_MAIN" | cut -d' ' -f1)"
    state_save   # F2：立即落盘，不等外层 Stage 5；否则中断后重跑会把自家受管 main 误判为人工修改
    rm -f "$tmp_orig" "$tmp_new"
    okf "已核验并备份发行版原始 nginx.conf → $backup（0600），替换为受管 main（无 server、无 80 监听）"
}

# nginx_main_is_pristine_fresh_install：盘上的 nginx 主配置是否仍是「本次由本向导
# 新装、且与同版本缓存包内原文逐字节相同」的发行包默认配置。成立时 Stage 5 的
# ensure_nginx_main 会备份并把它隔离成受管 main，所以 Stage 1 的静态 80 扫描不该把
# 它当第三方监听拦下——那是启动前的硬阻断，不是安装阶段该 fail-closed 的对象。
# 任何一项不成立（不是本次新装、被人工改过、拿不到可信缓存包）都返回非 0，
# 调用方继续按外来 80 监听报错。
nginx_main_is_pristine_fresh_install() {
    local fresh ver pkg
    [[ -f "$NGINX_MAIN" ]] || return 1
    fresh="$(state_get "pkg:nginx-fresh-install")"
    [[ -n "$fresh" ]] || return 1
    ver="$(nginx_installed_version)"
    [[ -n "$ver" && "$ver" == "$fresh" ]] || return 1
    LC_ALL=C pacman -Qo "$NGINX_MAIN" >/dev/null 2>&1 || return 1
    pkg="$(find_cached_nginx_pkg)" || return 1
    # 进程替换：不落盘，--check 仍然真正只读。
    cmp -s <(bsdtar -xOf "$pkg" "$NGINX_STOCK_CONF" 2>/dev/null) "$NGINX_MAIN"
}

# list_static_listen_80：静态列出残留 80 监听（排除本项目 bili.conf）
list_static_listen_80() {
    [[ -f "$NGINX_MAIN" ]] || return 0
    grep -rnE '^[[:space:]]*listen[[:space:]]+([^;]*:)?80([[:space:]]|;)' \
        "$NGINX_MAIN" "$(dirname "$NGINX_CONF")" "${NGINX_SITES_DIR:-$NGINX_ROOT/sites-enabled}" 2>/dev/null |
        grep -v "^$NGINX_CONF:" || true
}

# assert_no_listen_80_effective：启动前的硬门。用 `nginx -T`（解析 include 后的有效配置）
# 检查任何 80 监听；命中即 die，绝不允许“先 enable 起来再靠健康检查发现”。
assert_no_listen_80_effective() {
    local dump hit
    dump="$(mktemp /var/tmp/bili-nginx-effective.XXXXXX)"
    if ! sudo nginx -T >"$dump" 2>/dev/null; then
        rm -f "$dump"
        die "无法取得 nginx 有效配置（nginx -T 失败）；拒绝启用/启动 nginx"
    fi
    hit="$(grep -nE '^[[:space:]]*listen[[:space:]]+([^;]*:)?80([[:space:]]|;)' "$dump" | head -n3 || true)"
    if [[ -n "$hit" ]]; then
        while IFS= read -r line; do warn "有效配置里的 80 监听：$line"; done <<<"$hit"
        rm -f "$dump"
        die "nginx 有效配置仍包含 80 监听；拒绝 enable/start（不会先启动再检查）。请人工移走该 server/监听后重跑。"
    fi
    rm -f "$dump"
    okf "nginx 有效配置（含 include）不含任何 80 监听"
}

assert_perm() {
    local path="$1" want="$2" got
    got="$(stat -c '%U:%G:%a' "$path" 2>/dev/null || echo missing)"
    if [[ "$got" == "$want" ]]; then
        okf "$path $got"
    else
        problem "权限/属主异常：$path 为 $got，期望 $want"
    fi
}

# verify_bundle_and_render 用「bundle 里的钉住提交」反向锚定包内 render/：
#   * refs/heads/main 必须等于 ANCHOR_COMMIT，且该提交在 bundle 里可解析（SHA-1 身份，不可伪造）；
#   * render unit / snippet 必须与 commit 里的 deploy 模板逐字节相同；
#   * render nginx server 必须等于模板仅做 listen 4173→4273 后的指令（比较时忽略注释行）；
# 这样即使有人重算了 MANIFEST，也无法把任意 unit/nginx 配置塞进 root 安装路径。
verify_bundle_and_render() {
    local bundle tmp head expected actual
    bundle="$(find "$PACKAGE_DIR/repo" -maxdepth 1 -name '*.bundle' -print -quit)"
    [[ -z "$bundle" ]] && { problem "安装包缺少 git bundle"; return 0; }
    tmp="$(mktemp -d /var/tmp/bili-pkg-verify.XXXXXX)"
    if ! { git init -q --bare "$tmp/repo.git" &&
        git -C "$tmp/repo.git" fetch -q --no-tags "$bundle" 'refs/heads/*:refs/heads/*'; }; then
        problem "git bundle 无法 fetch（代码来源不可信）"
        rm -rf "$tmp"
        return 0
    fi
    head="$(git -C "$tmp/repo.git" rev-parse --verify --quiet refs/heads/main || true)"
    if [[ "$head" != "$ANCHOR_COMMIT" ]]; then
        problem "bundle 的 refs/heads/main 是 ${head:-空}，不是钉住版本 $ANCHOR_COMMIT"
    elif ! git -C "$tmp/repo.git" rev-parse --verify --quiet "$ANCHOR_COMMIT^{commit}" >/dev/null; then
        problem "bundle 里找不到钉住提交 $ANCHOR_COMMIT"
    else
        okf "bundle 独立验证：refs/heads/main = 钉住提交 $ANCHOR_COMMIT"
        if git -C "$tmp/repo.git" show "$ANCHOR_COMMIT:deploy/bili-monitor.service" 2>/dev/null |
            cmp -s - "$PACKAGE_DIR/render/etc/systemd/system/bili-monitor.service"; then
            okf "render unit 与钉住提交的 deploy/bili-monitor.service 逐字节相同"
        else
            problem "render unit 与钉住提交的 deploy/bili-monitor.service 不一致（拒绝信任包内 unit）"
        fi
        if git -C "$tmp/repo.git" show "$ANCHOR_COMMIT:deploy/nginx-locations.conf" 2>/dev/null |
            cmp -s - "$PACKAGE_DIR/render/etc/nginx/snippets/bili-locations.conf"; then
            okf "render nginx snippet 与钉住提交的 deploy/nginx-locations.conf 逐字节相同"
        else
            problem "render nginx snippet 与钉住提交的 deploy/nginx-locations.conf 不一致"
        fi
        expected="$tmp/expected-bili.conf"
        git -C "$tmp/repo.git" show "$ANCHOR_COMMIT:deploy/nginx-ecs-tunnel.conf" 2>/dev/null |
            sed 's|^    listen 127\.0\.0\.1:4173;$|    listen 127.0.0.1:4273;|' |
            grep -vE '^[[:space:]]*#' >"$expected" || true
        [[ -s "$expected" ]] || problem "无法从钉住提交重放 nginx server 模板"
        if [[ -s "$expected" ]]; then
            grep -vE '^[[:space:]]*#' "$PACKAGE_DIR/render/etc/nginx/conf.d/bili.conf" >"$tmp/actual-bili.conf"
            if cmp -s "$expected" "$tmp/actual-bili.conf"; then
                okf "render nginx server 与模板仅差 listen 4173→4273（忽略注释行）"
            else
                problem "render nginx server 与钉住提交模板不一致（除 listen 4173→4273 外不允许差异）"
            fi
        fi
    fi
    rm -rf "$tmp"

    # 与来源无关的安全断言：只回环、只有一条 listen、没有 80
    local conf="$PACKAGE_DIR/render/etc/nginx/conf.d/bili.conf"
    [[ "$(grep -cE '^[[:space:]]*listen[[:space:]]' "$conf")" == "1" ]] ||
        problem "render nginx server 的 listen 行数不是 1"
    grep -qE '^[[:space:]]*listen[[:space:]]+127\.0\.0\.1:4273;' "$conf" ||
        problem "render nginx server 不是 listen 127.0.0.1:4273"
    if grep -qE '^[[:space:]]*listen[[:space:]]+(0\.0\.0\.0|\*|\[::\])' "$conf"; then
        problem "render nginx server 出现非回环监听"
    fi
    if grep -qE '^[[:space:]]*proxy_pass[[:space:]]+[^;]*$' "$conf" &&
        ! grep -qE '^[[:space:]]*proxy_pass[[:space:]]+http://127\.0\.0\.1:8000;' "$conf"; then
        problem "render nginx server 的 proxy_pass 不是 127.0.0.1:8000"
    fi

    # render env：有效行、DB 路径、不得有未注释的 OSS/Cookie/通知
    local envf="$PACKAGE_DIR/render/etc/bili-monitor/env" active
    if [[ ! -f "$envf" ]]; then
        problem "安装包缺少 render/etc/bili-monitor/env"
        return 0
    fi
    active="$(sed -n 's/^\([A-Za-z_][A-Za-z0-9_]*\)=.*/\1/p' "$envf" | paste -sd, -)"
    if [[ "$active" == "BILI_DATABASE_PATH,PYTHONDONTWRITEBYTECODE,PYTHONUNBUFFERED" ]]; then
        okf "render env 有效行只有 DB 路径 + 两项 PYTHON*"
    else
        problem "render env 有效行不符：$active"
    fi
    grep -qx 'BILI_DATABASE_PATH=/srv/bili-monitor/monitor.sqlite' "$envf" ||
        problem "render env 的 DB 路径不是 /srv/bili-monitor/monitor.sqlite"
    if grep -qE '^BILI_(OSS_|COOKIE_FILE=|NOTIFICATION_CONFIG=)' "$envf"; then
        problem "render env 出现未注释的 OSS/Cookie/通知变量（本机必须保持未设置）"
    fi
}

check_port() {
    local port="$1" label="$2"
    port_busy "$port" || return 0
    if [[ "$port" == "$API_PORT" ]] && systemctl is-active --quiet "$SERVICE" &&
        [[ "$(state_get "commit:$APP_DIR")" == "$COMMIT" ]]; then
        notef "端口 $port 由本机已部署的 $SERVICE 占用（重跑场景）"
        return 0
    fi
    if [[ "$port" == "$WEB_PORT" ]] && systemctl is-active --quiet nginx &&
        [[ -n "$(state_get "file:$NGINX_CONF")" ]]; then
        notef "端口 $port 由本机已部署的 nginx 站点占用（重跑场景）"
        return 0
    fi
    problem "端口 $port 被占用（$(listen_addrs "$port")）：$label；默认拒绝与未知进程抢端口"
}

wait_api() {
    local attempt code
    for attempt in {1..40}; do
        # 库是本项目首启迁移创建的：文件一出现就登记，避免“首启/健康检查失败后重跑被判未知 DB”。
        if [[ -z "$(state_get "db:$DB_PATH")" ]] && sudo -u "$RUN_USER" test -s "$DB_PATH" 2>/dev/null; then
            state_set "db:$DB_PATH" "created-by-first-start:$(date -u +%Y%m%dT%H%M%SZ)"
            state_save
            okf "已登记首启迁移创建的库：$DB_PATH（保留，不覆盖、不删除）"
        fi
        code="$(http_code "http://127.0.0.1:$API_PORT/api/manage/ups")"
        [[ "$code" == "200" ]] && return 0
        sleep 1
    done
    return 1
}

publish_frontend() {
    local pkg_dist="$PACKAGE_DIR/frontend/dist" index_sha target release old
    index_sha="$(sha_of "$pkg_dist/index.html")"
    target="$(readlink -f "$SITE_ROOT/current" 2>/dev/null || true)"
    if [[ -n "$(state_get "symlink:$SITE_ROOT/current")" && "$target" != "$(state_get "symlink:$SITE_ROOT/current")" ]]; then
        die "current 符号链接已被改动（现在指向 ${target:-不可解析}）；拒绝覆盖，请人工确认后重跑"
    fi
    if [[ -n "$target" && -f "$target/index.html" && "$(sha_of "$target/index.html")" == "$index_sha" &&
        -n "$(state_get "symlink:$SITE_ROOT/current")" ]]; then
        okf "current 已指向同一产物：$target（跳过发布）"
        return 0
    fi
    release="$SITE_ROOT/releases/$(date -u +%Y%m%dT%H%M%SZ)-$SHORT"
    [[ ! -e "$release" ]] || die "发布目录已存在：$release（同秒重跑？请稍后再试）"
    sudo install -d -m 0755 -o root -g root "$release" || die "创建发布目录失败：$release"
    sudo rsync -a --delete "$pkg_dist/" "$release/" || die "同步前端产物失败"
    [[ "$(sha_of "$release/index.html")" == "$index_sha" ]] || die "发布后 index.html 与安装包不一致"
    sudo ln -sfn "$release" "$SITE_ROOT/current.tmp" || die "创建临时软链失败"
    sudo mv -Tf "$SITE_ROOT/current.tmp" "$SITE_ROOT/current" || die "原子切换 current 失败"
    [[ "$(readlink -f "$SITE_ROOT/current")" == "$release" ]] || die "current 切换后指向异常"
    state_set "symlink:$SITE_ROOT/current" "$release"
    state_set "release:$release" "$COMMIT"
    CONFIG_CHANGED=1
    okf "已原子切换 current → $release"
    # 只清理本项目命名规则（<UTC>-<7hex>）的历史版本，保留最新 5 个
    while IFS= read -r old; do
        [[ -n "$old" ]] || continue
        [[ "$SITE_ROOT/releases/$old" == "$(readlink -f "$SITE_ROOT/current")" ]] && continue
        sudo rm -rf -- "$SITE_ROOT/releases/$old" && okf "清理旧版本 $old"
    done < <(cd "$SITE_ROOT/releases" && ls -1d -- */ 2>/dev/null | sed 's#/$##' |
        grep -E '^[0-9]{8}T[0-9]{6}Z-[0-9a-f]{7}$' | LC_ALL=C sort -r | tail -n +6 || true)
}

# probe_static_assets 验证内容哈希 .js 的压缩与缓存头。
# 关键：nginx 只在客户端声明可接受 gzip 时才压缩，HEAD 不带 Accept-Encoding 永远看不到 gzip；
# 因此这里用真实 GET + --compressed，并挑一个大于 gzip_min_length(1024B) 的资源。
probe_static_assets() {
    local base="$1" asset="" candidate size header
    while IFS= read -r candidate; do
        size="$(stat -c %s "$SITE_ROOT/current/assets/$candidate" 2>/dev/null || printf '0')"
        if ((${size:-0} > 1024)); then
            asset="$candidate"
            break
        fi
    done < <(cd "$SITE_ROOT/current/assets" 2>/dev/null && ls -1 | grep '\.js$' || true)
    if [[ -z "$asset" ]]; then
        problem "current/assets 下没有大于 gzip_min_length(1024B) 的 .js 资源，无法验证压缩"
        return 0
    fi
    header="$(curl -sS --compressed -m 5 -D - -o /dev/null "$base/assets/$asset" | tr -d '\r')"
    grep -qi '^content-encoding: gzip' <<<"$header" &&
        okf "哈希资源 gzip（Accept-Encoding 协商，$asset）" ||
        problem "哈希资源未 gzip（核对 gzip_types/gzip_min_length，且请求必须声明 Accept-Encoding）"
    grep -qi '^cache-control: public, max-age=31536000, immutable' <<<"$header" &&
        okf "哈希资源 immutable 缓存头正确（$asset）" ||
        problem "哈希资源缺少 immutable 缓存头"
}

health_checks() {
    local body code asset header port addrs address processes version path
    body="$(curl -fsS -m 5 "http://127.0.0.1:$API_PORT/api/manage/ups" || true)"
    if [[ "$body" == '{"ups":[]}' ]]; then
        okf "空库 API：/api/manage/ups = {\"ups\":[]}"
    else
        problem "空库 API 返回异常：${body:0:120}"
    fi
    body="$(curl -fsS -m 5 "http://127.0.0.1:$API_PORT/api/manage/notifications" || true)"
    if [[ "$body" == *'"state":"off"'* && "$body" == *'"pending":0'* ]]; then
        okf "通知初始态：${body:0:80}（off，且未配置通知变量 ⇒ 无第三进程）"
    else
        problem "通知初始态不是 off/0：${body:0:120}"
    fi
    if [[ "$(http_code "http://127.0.0.1:$API_PORT/api/nope")" == "404" ]]; then
        okf "未知 API 直连 404"
    else
        problem "未知 API 直连未返回 404"
    fi
    for path in "/" "/manage"; do
        code="$(http_code "http://127.0.0.1:$WEB_PORT$path")"
        if [[ "$code" == "200" ]]; then okf "页面 $path 200"; else problem "页面 $path 返回 $code"; fi
    done
    if [[ "$(http_code "http://127.0.0.1:$WEB_PORT/api/manage/ups")" == "200" ]]; then
        okf "经 Nginx 的 /api/manage/ups 200（proxy_pass 127.0.0.1:$API_PORT）"
    else
        problem "经 Nginx 的 /api/manage/ups 非 200"
    fi
    if [[ "$(http_code "http://127.0.0.1:$WEB_PORT/api/nope")" == "404" ]]; then
        okf "经 Nginx 的未知 API 404（未回退 SPA）"
    else
        problem "经 Nginx 的未知 API 未返回 404"
    fi
    if curl -sSI -m 5 "http://127.0.0.1:$WEB_PORT/api/nope" | tr -d '\r' |
        grep -qi '^cache-control: no-store'; then
        okf "未知 API 带 Cache-Control: no-store"
    else
        problem "未知 API 缺少 Cache-Control: no-store"
    fi
    probe_static_assets "http://127.0.0.1:$WEB_PORT"
    for port in "$API_PORT" "$WEB_PORT"; do
        addrs="$(listen_addrs "$port")"
        if [[ -z "$addrs" ]]; then
            problem "端口 $port 未监听"
            continue
        fi
        while IFS= read -r address; do
            if [[ "$address" == "127.0.0.1:$port" ]]; then
                okf "端口 $port 只监听 $address"
            else
                problem "端口 $port 监听在非回环地址：$address"
            fi
        done <<<"$(printf '%s' "$addrs" | tr ',' '\n')"
    done
    # 只保证「本实例」不占用 80：先看 nginx 有效配置，再看 80 上的 socket 是否属于 nginx 进程。
    # 其它无关程序占用 80 不属于本项目的问题，也不去停它们。
    if sudo nginx -T 2>/dev/null | grep -qE '^[[:space:]]*listen[[:space:]]+([^;]*:)?80([[:space:]]|;)'; then
        problem "nginx 有效配置含 80 监听（本实例不应占用 80）"
    else
        okf "nginx 有效配置不含 80 监听"
    fi
    if sudo ss -H -ltnp 'sport = :80' 2>/dev/null | grep -q 'users:(("nginx"'; then
        problem "80 端口由 nginx 进程占用（本实例不应占用 80）"
    elif sudo ss -H -ltn 'sport = :80' 2>/dev/null | grep -q .; then
        notef "80 端口由其它程序占用（与本项目无关；未做任何处理）"
    else
        okf "80 端口无人监听"
    fi
    if systemctl is-active --quiet "$SERVICE"; then
        okf "$SERVICE active"
    else
        problem "$SERVICE 不是 active"
    fi
    processes="$(pgrep -u "$RUN_USER" -c python 2>/dev/null | head -n1 || true)"
    processes="${processes:-0}"
    if ((${processes:-0} >= 2)); then
        okf "$RUN_USER 名下 python 进程数 $processes（统一入口 + API + collector）"
    else
        problem "$RUN_USER 名下 python 进程数 $processes < 2"
    fi
    if sudo -u "$RUN_USER" test -s "$DB_PATH"; then
        version="$(sudo -u "$RUN_USER" sqlite3 "file:$DB_PATH?mode=ro" 'PRAGMA user_version;' 2>/dev/null || true)"
        if [[ "$version" =~ ^[0-9]+$ ]] && ((version > 0)); then
            okf "新空库已由迁移创建：$DB_PATH（schema user_version=$version）"
        else
            problem "数据库 schema 版本异常：${version:-空}"
        fi
    else
        problem "数据库不存在或为空：$DB_PATH"
    fi
    if sudo journalctl -u "$SERVICE" --since '-5 min' --no-pager 2>/dev/null | grep -qi 'traceback'; then
        problem "journal 出现 traceback：sudo journalctl -u $SERVICE -n 50 --no-pager"
    else
        okf "journal 无 traceback"
    fi
}

preflight() {
    local owner path tool package_version missing=()
    resolve_package
    verify_package "$PACKAGE_DIR"
    state_load
    okf "安装包 MANIFEST 校验通过：$PACKAGE_DIR"

    COMMIT="$(sed -n 's/^commit=//p' "$PACKAGE_DIR/VERSION" | head -n1)"
    SHORT="$(sed -n 's/^short=//p' "$PACKAGE_DIR/VERSION" | head -n1)"
    [[ "$COMMIT" =~ ^[0-9a-f]{40}$ ]] || die "VERSION 里的 commit 非法：$COMMIT"
    [[ "$SHORT" =~ ^[0-9a-f]{7,40}$ ]] || die "VERSION 里的 short 非法：$SHORT"
    okf "锚点 $(anchor_label)"
    [[ "$COMMIT" == "$ANCHOR_COMMIT" ]] ||
        problem "安装包版本 $COMMIT 不是进入向导时固定的锚点 $ANCHOR_COMMIT（来源：$ANCHOR_SOURCE；拒绝安装其他版本）"
    [[ "$SHORT" == "${ANCHOR_COMMIT:0:${#SHORT}}" ]] || problem "VERSION 的 short=$SHORT 与钉住版本不一致"
    okf "版本 $SHORT（$COMMIT），打包于 $(sed -n 's/^created_utc=//p' "$PACKAGE_DIR/VERSION")"

    local want_index got_index
    want_index="$(sed -n 's/^frontend_dist_index_sha256=//p' "$PACKAGE_DIR/VERSION")"
    got_index="$(sha_of "$PACKAGE_DIR/frontend/dist/index.html")"
    [[ "$want_index" == "$got_index" ]] || problem "生产产物 index.html 与 VERSION 记录不一致"
    if grep -rIl -- '__preview-fixtures' "$PACKAGE_DIR/frontend/dist" >/dev/null 2>&1; then
        problem "生产产物含 mock 自检路由（不是纯生产 dist）"
    fi
    okf "生产 dist 与 VERSION 一致（index.html ${got_index:0:12}…）"
    verify_bundle_and_render

    for tool in pacman sudo systemctl ss curl git rsync sha256sum install mktemp awk sed; do
        command -v "$tool" >/dev/null 2>&1 || missing+=("$tool")
    done
    ((${#missing[@]} == 0)) || problem "缺少基础命令：${missing[*]}"
    for tool in sqlite3 journalctl pgrep bsdtar; do
        command -v "$tool" >/dev/null 2>&1 || notef "$tool 尚未安装（依赖阶段会补 sqlite）"
    done
    if ! nginx_available; then
        warn "nginx 尚未安装：当前不能证明发行包默认配置安全。安装后本向导会先做原始配置核验（pacman 元数据 + 同版本缓存包逐字节比对）、备份并隔离默认站点，启动前再对有效配置做 80 硬检查；无法确认原始包则 fail closed。"
    fi

    if package_version="$(LC_ALL=C pacman -Si nginx 2>/dev/null | sed -n 's/^Version[[:space:]]*:[[:space:]]*//p' | head -n1)" &&
        [[ -n "$package_version" ]]; then
        okf "软件源中 nginx 可安装：$package_version"
    else
        problem "本地软件源库查不到 nginx（可先人工 sudo pacman -Sy 后重跑；本向导不执行 -Syu）"
    fi

    if [[ -d "$NGINX_ROOT" ]]; then
        local backup_record
        backup_record="$(state_get "backup:$NGINX_MAIN")"
        while IFS= read -r path; do
            # 本向导自己安装/备份的文件不是“他人遗留”；只有真正未识别的才报冲突
            [[ "$path" == "$NGINX_CONF" || "$path" == "$NGINX_SNIPPET" ]] && continue
            [[ -n "${STATE[file:$path]:-}" ]] && continue
            [[ -n "$backup_record" && "$path" == "$backup_record" ]] && continue
            if [[ "$path" == "$NGINX_MAIN".bili-local-deployment.*.bak ]]; then
                problem "本向导旧版本在 /etc/nginx 留下的备份：$path；请人工**移走**（不要删除数据、也不要原地修改）后重跑"
                continue
            fi
            LC_ALL=C pacman -Qo "$path" >/dev/null 2>&1 && continue
            problem "/etc/nginx 下有未被任何包拥有的文件：$path（pacman 可能报文件冲突；本向导不用 --overwrite，也不会删它；请人工确认来源后移走/改名再重跑）"
        done < <(find "$NGINX_ROOT" -maxdepth 2 -type f -print)
    fi

    [[ -d /srv ]] || problem "/srv 不存在"

    if getent passwd "$RUN_USER" >/dev/null 2>&1; then
        if [[ "$(id -u "$RUN_USER")" == "0" ]]; then
            problem "$RUN_USER 是 root 身份账号，拒绝使用"
        elif [[ "$(state_get "account:$RUN_USER")" == "$(id -u "$RUN_USER")" ]]; then
            notef "复用已记录的账号 $RUN_USER（uid=$(id -u "$RUN_USER")）"
        else
            problem "已存在未识别的账号 $RUN_USER（uid=$(id -u "$RUN_USER")）：拒绝使用或修改"
        fi
    else
        notef "账号 $RUN_USER 不存在（将由向导创建）"
    fi

    for path in "$DEPLOY_ROOT" "$APP_DIR" "$DB_PATH" "$BACKUP_DIR" "$CRED_DIR" \
        "$SITE_ROOT" "$SITE_ROOT/releases" "$SITE_ROOT/current" \
        "$(dirname "$CONF_ENV")" "$CONF_ENV" "$UNIT_FILE" \
        "$NGINX_ROOT/conf.d" "$NGINX_CONF" "$NGINX_ROOT/snippets" "$NGINX_SNIPPET" "$UV_SYSTEM"; do
        owner="$(path_owner "$path")"
        case "$owner" in
            absent) notef "不存在：$path（将创建）" ;;
            ours) notef "由本向导上次创建：$path（可安全更新）" ;;
            db) notef "首启迁移创建的库：$path（保留，不覆盖、不删除）" ;;
            modified) problem "内容与上次安装记录不同：$path（拒绝覆盖；请人工确认并移走/改名，不要删除数据库或真实配置）" ;;
            *)
                if [[ "$path" == "$DB_PATH" ]]; then
                    problem "已存在未登记数据库：$path；本向导**不删除、不覆盖数据库**。请保留数据库与现场，不删除、不移动数据库、不手改 state，并按 docs/deployment/README.md 人工核查来源后处理"
                else
                    problem "已存在且未识别：$path（默认拒绝覆盖未知对象；请人工确认来源后移走/改名，不要删除数据库或真实配置）"
                fi
                ;;
        esac
    done

    check_port "$API_PORT" "后端 API"
    check_port "$WEB_PORT" "Nginx 站点"
    local static80
    static80="$(list_static_listen_80)"
    if [[ -n "$static80" ]]; then
        while IFS= read -r line; do
            # 本次新装、未被改动过的包默认 main：Stage 5 会备份并隔离，不算阻塞。
            if [[ "$line" == "$NGINX_MAIN":* ]] && nginx_main_is_pristine_fresh_install; then
                notef "包自带默认站点（$line）：本次新装且与缓存包原文一致，Stage 5 会备份并隔离"
            else
                problem "已存在的 80 监听：$line（本向导会硬阻断，不会启动对外监听 80 的 nginx；请人工移走该 server/监听后重跑）"
            fi
        done <<<"$static80"
    else
        notef "静态扫描：现有 nginx 配置中无 80 监听"
    fi
}

run_wizard() {
    while (($#)); do
        case "$1" in
            --package) PACKAGE_DIR="${2:?--package 需要目录}"; shift 2 ;;
            --commit) CLI_COMMIT="${2:?--commit 需要 40 位 SHA}"; shift 2 ;;
            --check) MODE="check"; shift ;;
            -h | --help) usage; exit 0 ;;
            *) die "未知参数 '$1'（--help 查看用法）" ;;
        esac
    done

    [[ "${EUID:-$(id -u)}" -ne 0 ]] || die "请用普通用户运行本脚本（不要 sudo 整个脚本）；root 动作由脚本按需调用 sudo"
    # 安装模式必须在真实终端里跑：confirm/pause 需要人工回答，sudo 也需要 TTY。
    [[ "$MODE" == "check" ]] || need_tty
    resolve_anchor
    PACKAGE_DIR="${PACKAGE_DIR:-${BILI_DEPLOY_PACKAGE:-$(default_package_dir)}}"

    # 不 source 任何 .env，也不把操作员的 BILI_* 带进任何子进程（后端只读 /etc/bili-monitor/env）。
    local inherited=() name
    while IFS= read -r name; do [[ -n "$name" ]] && inherited+=("$name"); done \
        < <(compgen -v | LC_ALL=C grep -E '^BILI_' || true)
    if ((${#inherited[@]})); then
        warn "当前 shell 有 ${inherited[*]}；本向导不使用（后端只认 /etc/bili-monitor/env），并从本进程环境清除"
        for name in "${inherited[@]}"; do unset -v "$name"; done
    fi

    TOTAL_STAGES=7
    if [[ "$MODE" == "check" ]]; then
        printf '\n  %s只读预检（--check）：不写文件、不调用 sudo%s\n\n' "$BOLD" "$RESET"
    else
        banner "bili_charge_dynamics 本机「与云端同形式」部署"
        note "路径与 unit 形式与云端一致；唯一配置差异是网页 listen 127.0.0.1:4273（云端 4173）。"
        note "本机不启用 OSS / Cookie / 飞书通知：env 里这些变量保持「不设置」，只托管 API＋collector。"
        note "会先用只读预检验证安装包与冲突面，再逐阶段确认；Ctrl-C 可随时退出，重跑只动自己记录过的对象。"
    fi

    # ── Stage 1 ──────────────────────────────────────────────────────────────
    stage "预检（只读）：安装包、版本、路径与端口冲突"
    say "本阶段不写文件、不调用 sudo。"
    PROBLEMS=()
    preflight
    problem_summary
    ((${#PROBLEMS[@]} == 0)) || die "预检未通过；未做任何改动"
    okf "预检通过：目标路径/端口/账号均无未知占用"
    if [[ "$MODE" == "check" ]]; then
        printf '\n  只读预检通过（未写文件、未调用 sudo）。正式安装：\n'
        printf '      scripts/setup-local-deployment.sh --package %s\n\n' "$PACKAGE_DIR"
        exit 0
    fi
    pause "按 Enter 进入依赖安装（第一次使用 sudo）"

    # ── Stage 2 ──────────────────────────────────────────────────────────────
    stage "管理员依赖与 uv（开始使用 sudo）"
    say "将执行（不含 -Syu；不改 SSH/swap/防火墙；不用 --overwrite；不动其他站点目录）："
    step "sudo pacman -S --needed --noconfirm nginx git rsync sqlite"
    step "sudo install -m 0755 -o root -g root <安装包>/uv/uv $UV_SYSTEM"
    step "sudo install -d -m 0755 -o root -g root $STATE_DIR"
    note "uv 只作为 root 装进 $UV_SYSTEM；bili 的 CPython 与 uv 缓存都落在 /home/bili，"
    note "不复用 kevin 的 ~/.local、不 source 任何 ~/.local 启动脚本。"
    confirm_strict "授权并开始安装系统依赖？" || die "已取消；未做任何系统改动"
    sudo_auth
    local nginx_preinstalled=0 nginx_fresh_ver=""
    LC_ALL=C pacman -Q nginx >/dev/null 2>&1 && nginx_preinstalled=1
    sudo pacman -S --needed --noconfirm nginx git rsync sqlite ||
        die "pacman 安装失败（若提示数据库过期，请人工 sudo pacman -Sy 后重跑；本向导不执行 -Syu）"
    command -v nginx >/dev/null || die "pacman 退出码为 0 但找不到 nginx"
    okf "nginx $(LC_ALL=C nginx -v 2>&1 | sed 's/^nginx version: //')"
    okf "git $(LC_ALL=C git --version | awk '{print $3}')"
    okf "rsync $(LC_ALL=C rsync --version | head -n1 | awk '{print $3}')"
    sudo install -d -m 0755 -o root -g root "$STATE_DIR" || die "创建 $STATE_DIR 失败"
    if ((nginx_preinstalled == 0)); then
        nginx_fresh_ver="$(nginx_installed_version)"
        [[ -n "$nginx_fresh_ver" ]] || die "装完取不到 nginx 包版本（pacman -Q nginx 失败）"
        state_set "pkg:nginx-fresh-install" "$nginx_fresh_ver"
        okf "记录本次新装 nginx $nginx_fresh_ver：Stage 5 允许对“与缓存包逐字节相同”的原始配置做隔离"
    else
        notef "nginx 在本次运行前已安装：不会自动改写它的主配置（需人工确认，或由本向导上次登记过的受管 main）"
    fi
    local uv_pkg_sha uv_installed_sha
    uv_pkg_sha="$(sha_of "$(pkg_file uv/uv)")"
    if [[ -f "$UV_SYSTEM" && "$(state_get "file:$UV_SYSTEM")" == "$uv_pkg_sha" &&
        "$(sha_of "$UV_SYSTEM")" == "$uv_pkg_sha" ]]; then
        okf "uv 已是安装包版本：$("$UV_SYSTEM" --version)"
    else
        sudo install -m 0755 -o root -g root "$(pkg_file uv/uv)" "$UV_SYSTEM" || die "安装 uv 失败"
        uv_installed_sha="$(sha_of "$UV_SYSTEM")"
        [[ "$uv_installed_sha" == "$uv_pkg_sha" ]] || die "安装后的 uv 与安装包不一致"
        state_set "file:$UV_SYSTEM" "$uv_installed_sha"
        okf "已安装 uv：$("$UV_SYSTEM" --version)"
    fi
    state_set "pkg:$COMMIT" "$PACKAGE_DIR"
    state_save
    pause "依赖就绪。按 Enter 继续建账号与目录"

    # ── Stage 3 ──────────────────────────────────────────────────────────────
    stage "运行账号与目录（$RUN_USER、/srv、/etc/bili-monitor）"
    say "与云端同路径同属主：/srv/bili-monitor 归 $RUN_USER；/srv/dynamics-viewer 与 /etc/bili-monitor 归 root。"
    step "useradd -m -s /bin/bash $RUN_USER（已记录则跳过）"
    step "$DEPLOY_ROOT 0755、backup/ 0755、credentials/ 0700（空目录，无任何凭据）"
    step "$SITE_ROOT/releases、/etc/bili-monitor、$NGINX_ROOT/{conf.d,snippets}"
    note "不触碰 /srv 下既有的 ftp/、http/ 等无关目录。"
    confirm_strict "创建账号与目录？" || die "已取消；未做改动"
    if getent passwd "$RUN_USER" >/dev/null 2>&1; then
        okf "复用已记录账号 $RUN_USER（uid=$(id -u "$RUN_USER")）"
    else
        sudo useradd -m -s /bin/bash "$RUN_USER" || die "useradd 失败"
        getent group "$RUN_USER" >/dev/null 2>&1 ||
            { sudo groupadd "$RUN_USER" && sudo usermod -g "$RUN_USER" "$RUN_USER"; } ||
            die "创建 $RUN_USER 组失败"
        okf "已创建账号 $RUN_USER（uid=$(id -u "$RUN_USER")，home=/home/$RUN_USER）"
    fi
    state_set "account:$RUN_USER" "$(id -u "$RUN_USER")"
    sudo install -d -m 0755 -o "$RUN_USER" -g "$RUN_USER" "$DEPLOY_ROOT" "$BACKUP_DIR" ||
        die "创建 $DEPLOY_ROOT 失败"
    sudo install -d -m 0700 -o "$RUN_USER" -g "$RUN_USER" "$CRED_DIR" || die "创建 credentials 失败"
    sudo install -d -m 0755 -o root -g root "$SITE_ROOT" "$SITE_ROOT/releases" \
        "$(dirname "$CONF_ENV")" "$NGINX_ROOT/conf.d" "$NGINX_ROOT/snippets" || die "创建系统目录失败"
    if [[ -n "$(sudo find "$CRED_DIR" -mindepth 1 -maxdepth 1 -print -quit)" ]]; then
        die "$CRED_DIR 非空：本向导不处理未知凭据；请人工确认后重跑"
    fi
    for path in "$DEPLOY_ROOT" "$BACKUP_DIR" "$CRED_DIR" "$SITE_ROOT" "$SITE_ROOT/releases" \
        "$(dirname "$CONF_ENV")" "$NGINX_ROOT/conf.d" "$NGINX_ROOT/snippets"; do
        state_set "dir:$path" "$(stat -c '%U:%G:%a' "$path")"
        okf "$path $(stat -c '%U:%G:%a' "$path")"
    done
    notef "未来若启用凭据，沿用云端文件名：$COOKIE_PATH、$NOTIFICATION_PATH（本阶段不生成）"
    state_save
    pause "账号与目录就绪。按 Enter 继续检出代码"

    # ── Stage 4 ──────────────────────────────────────────────────────────────
    stage "代码检出与独立 Python 环境（以 $RUN_USER 身份）"
    say "代码来源：安装包内 git bundle（main@$SHORT），不克隆开发仓库工作区、不 import 开发 .venv。"
    say "依赖：$UV_SYSTEM sync --locked --no-dev --python 3.12，venv 就地 $APP_DIR/.venv。"
    note "首次需要访问 PyPI 与 uv 的 CPython 分发；缓存和解释器都在 /home/bili（ProtectHome=read-only 允许执行）。"
    confirm_strict "检出代码并安装锁定依赖？" || die "已取消；未做改动"
    assert_anchor_stable            # 受信 HEAD 中途变动 / 包提交与锚点不一致 → 拒绝
    verify_package "$PACKAGE_DIR"   # 以 root/bili 使用包内容前再校验一次 MANIFEST 与信任锚
    verify_bundle_and_render
    local bundle head_now real_python python_version remote_https existing_origin
    bundle="$(find "$PACKAGE_DIR/repo" -maxdepth 1 -name '*.bundle' -print -quit)"
    if [[ -e "$APP_DIR" ]]; then
        require_managed "$APP_DIR" "代码目录"
        [[ -d "$APP_DIR/.git" ]] || die "$APP_DIR 存在但不是 git 检出；拒绝覆盖"
        head_now="$(run_as_bili git -C "$APP_DIR" rev-parse HEAD 2>/dev/null || true)"
        [[ "$head_now" == "$COMMIT" ]] ||
            die "$APP_DIR 已检出的提交 ${head_now:-未知} ≠ $COMMIT；拒绝就地切换，请人工处理"
        okf "复用已检出代码（HEAD=$SHORT）"
    else
        run_as_bili git clone --quiet --branch main --single-branch "$bundle" "$APP_DIR" ||
            die "git clone 失败"
        okf "已检出到 $APP_DIR"
    fi
    [[ "$(run_as_bili git -C "$APP_DIR" rev-parse HEAD)" == "$COMMIT" ]] || die "检出提交与安装包不一致"
    [[ -z "$(run_as_bili git -C "$APP_DIR" status --porcelain)" ]] || die "检出工作区不干净，拒绝继续"
    # 离线来源保留为 local-bundle；真实远端 origin 留给后续升级（本地与云端同一升级流程）。
    if run_as_bili git -C "$APP_DIR" remote get-url origin >/dev/null 2>&1; then
        run_as_bili git -C "$APP_DIR" remote rename origin local-bundle >/dev/null 2>&1 || true
    fi
    if ! run_as_bili git -C "$APP_DIR" remote get-url local-bundle >/dev/null 2>&1; then
        run_as_bili git -C "$APP_DIR" remote add local-bundle "$bundle" >/dev/null 2>&1 || true
    fi
    remote_https="$(sed -n 's/^remote_https=//p' "$PACKAGE_DIR/VERSION" | head -n1)"
    if [[ "$remote_https" == https://* ]]; then
        existing_origin="$(run_as_bili git -C "$APP_DIR" remote get-url origin 2>/dev/null || true)"
        if [[ -z "$existing_origin" ]]; then
            if run_as_bili git -C "$APP_DIR" remote add origin "$remote_https"; then
                okf "已配置升级用 origin：$remote_https"
            else
                warn "添加 origin 失败；升级前请按 docs/deployment/README.md 手工补 origin"
            fi
        elif [[ "$existing_origin" == "$remote_https" ]]; then
            okf "复用已有 origin：$remote_https"
        else
            warn "已有 origin 指向别处，保留不动：$existing_origin"
        fi
    else
        warn "安装包未记录 https 远端：本次不配置 origin；升级前请按 docs/deployment/README.md 补充"
    fi
    state_set "dir:$APP_DIR" "$(stat -c '%U:%G:%a' "$APP_DIR")"
    state_set "commit:$APP_DIR" "$COMMIT"
    state_save

    say "同步锁定依赖（--locked --no-dev，使用 uv 管理的 CPython 3.12）…"
    run_as_bili /usr/bin/env UV_PYTHON_PREFERENCE=only-managed "$UV_SYSTEM" sync \
        --locked --no-dev --python 3.12 --directory "$APP_DIR" ||
        die "uv sync 失败（网络/缓存受限时请修复后直接重跑本向导；已完成的步骤会复用）"
    [[ -d "$APP_DIR/.venv" && ! -L "$APP_DIR/.venv" ]] || die ".venv 不是独立目录：$APP_DIR/.venv"
    python_version="$(run_as_bili "$APP_DIR/.venv/bin/python" -V 2>&1)"
    [[ "$python_version" == Python\ 3.12.* ]] || die "venv Python 不是 3.12：$python_version"
    run_as_bili "$APP_DIR/.venv/bin/python" -c 'import fastapi, uvicorn, httpx, oss2, requests' ||
        die "venv 缺少运行时依赖"
    if run_as_bili "$APP_DIR/.venv/bin/python" -c 'import pytest' >/dev/null 2>&1; then
        die "venv 内存在 pytest：不是 --no-dev 生产环境"
    fi
    real_python="$(run_as_bili readlink -f "$APP_DIR/.venv/bin/python")"
    [[ "$real_python" == /home/$RUN_USER/.local/share/uv/python/* ]] ||
        die "解释器不在 /home/$RUN_USER（疑似误用系统或开发解释器）：$real_python"
    okf "venv：$python_version（$real_python）"
    okf "无 dev 依赖（pytest 不存在）"
    state_set "venv:$APP_DIR" "$python_version"
    state_save
    pause "代码与依赖就绪。按 Enter 继续安装系统配置"

    # ── Stage 5 ──────────────────────────────────────────────────────────────
    stage "系统配置：环境文件、systemd unit、Nginx 站点"
    say "将安装 4 个 root 拥有的文件（内容来自安装包，SHA256 已在预检校验）："
    step "$CONF_ENV 0600 root:root（有效行仅 BILI_DATABASE_PATH + 两项 PYTHON*）"
    step "$UNIT_FILE 0644 root:root（与 deploy/bili-monitor.service 逐字节相同）"
    step "$NGINX_SNIPPET 0644 root:root（与 deploy/nginx-locations.conf 逐字节相同）"
    step "$NGINX_CONF 0644 root:root（唯一差异 listen 127.0.0.1:$WEB_PORT）"
    note "若 nginx 主配置尚未 include conf.d/*.conf，会在备份后精准插入一行并立即 nginx -t；失败自动回滚。"
    confirm_strict "安装以上配置？" || die "已取消；未做改动"
    assert_anchor_stable                # 再确认锚点/源 HEAD 未漂移
    verify_package "$PACKAGE_DIR"       # 重新校验 MANIFEST/属主/无软链
    verify_bundle_and_render            # 再确认 render 与锚点提交一致（不信任可重算的 MANIFEST）
    ((${#PROBLEMS[@]} == 0)) || { problem_summary; die "安装前复校验未通过；未写入任何 root 配置"; }
    for path in "$CONF_ENV" "$UNIT_FILE" "$NGINX_SNIPPET" "$NGINX_CONF"; do
        require_managed "$path" "目标文件"
    done
    install_managed render/etc/bili-monitor/env "$CONF_ENV" 0600
    install_managed render/etc/systemd/system/bili-monitor.service "$UNIT_FILE" 0644
    install_managed render/etc/nginx/snippets/bili-locations.conf "$NGINX_SNIPPET" 0644
    install_managed render/etc/nginx/conf.d/bili.conf "$NGINX_CONF" 0644
    sudo systemctl daemon-reload || die "systemctl daemon-reload 失败"
    ensure_nginx_main
    sudo nginx -t || die "nginx -t 失败；未启动任何服务（主配置已按需登记/回滚）"
    local static80 line
    static80="$(list_static_listen_80)"
    if [[ -n "$static80" ]]; then
        while IFS= read -r line; do warn "遗留 80 监听：$line"; done <<<"$static80"
        die "存在非本项目的 80 监听；拒绝继续（本向导不会启动会对外监听 80 的 nginx）"
    fi
    okf "静态扫描：nginx 站点/主配置中无 80 监听"
    assert_no_listen_80_effective
    local active_lines
    active_lines="$(sudo sed -n 's/^\([A-Za-z_][A-Za-z0-9_]*\)=.*/\1/p' "$CONF_ENV" | paste -sd, -)"
    [[ "$active_lines" == "BILI_DATABASE_PATH,PYTHONDONTWRITEBYTECODE,PYTHONUNBUFFERED" ]] ||
        die "env 有效行不符合预期：$active_lines（不允许空赋值的 OSS/Cookie/通知变量）"
    okf "env 有效行：$active_lines"
    state_save
    pause "配置已安装。按 Enter 继续发布前端"

    # ── Stage 6 ──────────────────────────────────────────────────────────────
    stage "前端静态产物原子发布"
    say "把安装包内的生产 dist（$SHORT 干净快照构建）发布到 $SITE_ROOT/releases/<UTC>-$SHORT，再原子切换 current。"
    note "保留最新 5 个本项目命名规则的版本；不就地覆盖旧产物，避免已缓存哈希资源 404。"
    confirm_strict "发布前端？" || die "已取消；未做改动"
    require_managed "$SITE_ROOT/current" "current 符号链接"
    publish_frontend
    state_save
    pause "前端已发布。按 Enter 继续校验与启动"

    # ── Stage 7 ──────────────────────────────────────────────────────────────
    stage "校验、启动与只读健康检查"
    say "先只做校验，不改变运行状态：nginx -t、systemd-analyze verify、权限与 env 有效行复核。"
    sudo nginx -t || die "nginx -t 失败；未启动任何服务"
    okf "nginx -t 通过"
    assert_no_listen_80_effective
    local verify_output
    if ! verify_output="$(sudo systemd-analyze verify "$UNIT_FILE" 2>&1)"; then
        printf '%s\n' "$verify_output" | sed 's/^/    /'
        die "systemd-analyze verify 报告问题；未启动服务"
    fi
    [[ -n "$verify_output" ]] && printf '%s\n' "$verify_output" | sed 's/^/    /'
    okf "systemd unit 校验通过"
    PROBLEMS=()
    assert_perm "$CONF_ENV" root:root:600
    assert_perm "$UNIT_FILE" root:root:644
    assert_perm "$NGINX_CONF" root:root:644
    assert_perm "$NGINX_SNIPPET" root:root:644
    assert_perm "$CRED_DIR" "$RUN_USER:$RUN_USER:700"
    assert_perm "$BACKUP_DIR" "$RUN_USER:$RUN_USER:755"
    active_lines="$(sudo sed -n 's/^\([A-Za-z_][A-Za-z0-9_]*\)=.*/\1/p' "$CONF_ENV" | paste -sd, -)"
    [[ "$active_lines" == "BILI_DATABASE_PATH,PYTHONDONTWRITEBYTECODE,PYTHONUNBUFFERED" ]] ||
        problem "env 有效行异常：$active_lines"
    problem_summary
    ((${#PROBLEMS[@]} == 0)) || die "校验未通过；未启动服务"

    say "接下来将：enable --now nginx、enable --now $SERVICE（配置有变化时 restart），"
    say "然后只对 127.0.0.1:$API_PORT / 127.0.0.1:$WEB_PORT 做只读 GET 健康检查（空库零上游请求）。"
    confirm_strict "启动 nginx 与 $SERVICE？" || die "已取消；配置已安装，服务未启动（可重跑本向导再启动）"
    # 启动前最后一次硬检查：有效配置（含 include）里不允许出现任何 80 监听。
    # 这里没有“确认覆盖”的选项：绝不允许先 enable 起来再靠健康检查发现暴露。
    assert_no_listen_80_effective
    if systemctl is-active --quiet nginx; then
        sudo systemctl reload nginx || sudo systemctl restart nginx || die "nginx 重载失败"
        okf "nginx 已重载"
    else
        sudo systemctl enable --now nginx || die "nginx 启动失败：sudo journalctl -u nginx -n 30"
        okf "nginx 已启用并启动"
    fi
    if systemctl is-active --quiet "$SERVICE"; then
        if ((CONFIG_CHANGED)); then
            sudo systemctl restart "$SERVICE" || die "重启 $SERVICE 失败"
            okf "$SERVICE 已按新配置重启"
        else
            okf "$SERVICE 已在运行（无需重启）"
        fi
    else
        sudo systemctl enable --now "$SERVICE" || true
    fi
    # 先落盘“服务已启动/库已登记”：健康检查失败时重跑仍能认出自己的产物，而不是被判未知对象。
    state_set "service:$SERVICE" "start-attempt:$(date -u +%Y%m%dT%H%M%SZ)"
    state_save
    if ! wait_api; then
        sudo systemctl status "$SERVICE" --no-pager -l 2>&1 | head -n 20
        sudo journalctl -u "$SERVICE" -n 30 --no-pager 2>&1
        die "$SERVICE 未在 40 秒内就绪；配置已安装，可用上面的日志定位后重跑"
    fi
    okf "$SERVICE 已就绪（127.0.0.1:$API_PORT）"

    PROBLEMS=()
    health_checks
    problem_summary
    ((${#PROBLEMS[@]} == 0)) || die "健康检查未全部通过；服务已启动，配置与库已登记（重跑不会动数据库），请看上面的问题项"
    state_set "service:$SERVICE" "active:$(date -u +%Y%m%dT%H%M%SZ)"
    [[ -n "$(state_get "db:$DB_PATH")" ]] ||
        state_set "db:$DB_PATH" "created-by-first-start:$(date -u +%Y%m%dT%H%M%SZ)"
    state_save

    finish
    open_url "http://127.0.0.1:$WEB_PORT/"
    note "页面：http://127.0.0.1:$WEB_PORT/    管理页：http://127.0.0.1:$WEB_PORT/manage"
    note "证据与状态：$STATE_FILE（root 0644）；安装包：$PACKAGE_DIR"
    note "本机未启用 OSS/Cookie/飞书通知（变量不存在，不是空字符串）：只有 API＋collector 两进程，通知闸门 off。"
    note "未来启用沿用云端路径：$COOKIE_PATH、$NOTIFICATION_PATH（目录 0700），填真实值后重启。"
    note "重跑：本向导可重复运行，只覆盖自己记录且未被修改的对象；未识别对象/端口占用会拒绝。"
    note "停止（需你人工确认）：sudo systemctl stop $SERVICE nginx；卸载依据：$STATE_FILE 内的记录。"
}

run_wizard "$@"
exit
